/*
 * 09 — GINGERBREAD CHRISTMAS WORKSHOP
 * Pure Canvas 2D. Call draw(ctx, timeInSeconds, width, height).
 * One scene; deterministic 20-second loop; designed at 1920 x 1080.
 * The piping carriage, four-place indexing table and delivery belt share
 * one clock. Cookie resets occur only inside the solid return housings.
 * No assets, timers, DOM, filters, blur or glow.
 * Export metadata is a contract for the host encoder, not a video encoder.
 * Apply 100,000,000 bits/second CBR in the exporting application.
 */
function draw(ctx, time, width, height) {
  if (!ctx || !Number.isFinite(time) || !(width > 0) || !(height > 0)) return;
  const t = time;
  const duration = 20;
  const sceneCount = 1;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  const unit = Math.min(width / 1920, minSide / 1080);
  const PI = Math.PI, TAU = PI * 2;
  const phase = TAU * (currentScene + sceneProgress);
  const mod = (x, n) => ((x % n) + n) % n;
  const clamp = x => Math.max(0, Math.min(1, x));
  const ease = x => { x = clamp(x); return x * x * x * (x * (x * 6 - 15) + 10); };
  const between = (a, b, x) => ease((x - a) / (b - a));
  const lerp = (a, b, p) => a + (b - a) * p;
  const hash = i => { const n = Math.sin(i * 127.1 + 311.7) * 43758.5453; return n - Math.floor(n); };
  const C = {
    paper: '#f2eadb', ink: '#553b30', copper: '#aa704b', cream: '#fff8e9',
    red: '#843b3a', redDark: '#632c31', green: '#355448', greenDark: '#263d35',
    biscuit: '#b77a47', biscuitLight: '#d29a60', edge: '#895833', brass: '#b99a64'
  };

  function poly(points, fill, stroke, line = 1) {
    ctx.beginPath(); ctx.moveTo(points[0][0], points[0][1]);
    for (let i = 1; i < points.length; i++) ctx.lineTo(points[i][0], points[i][1]);
    ctx.closePath();
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = line; ctx.stroke(); }
  }
  function round(x, y, w, h, r, fill, stroke, line = 1) {
    r = Math.min(r, w / 2, h / 2);
    ctx.beginPath(); ctx.moveTo(x + r, y); ctx.lineTo(x + w - r, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + r); ctx.lineTo(x + w, y + h - r);
    ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h); ctx.lineTo(x + r, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - r); ctx.lineTo(x, y + r);
    ctx.quadraticCurveTo(x, y, x + r, y); ctx.closePath();
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = line; ctx.stroke(); }
  }
  function oval(x, y, rx, ry, fill, stroke, line = 1) {
    ctx.beginPath(); ctx.ellipse(x, y, rx, ry, 0, 0, TAU);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = line; ctx.stroke(); }
  }
  function line(points, color, lineWidth = 2) {
    ctx.beginPath(); ctx.moveTo(points[0][0], points[0][1]);
    for (let i = 1; i < points.length; i++) ctx.lineTo(points[i][0], points[i][1]);
    ctx.strokeStyle = color; ctx.lineWidth = lineWidth; ctx.stroke();
  }
  function tracked(text, x, y, size, tracking, maxWidth, color, family = 'Arial, sans-serif') {
    ctx.save(); ctx.textAlign = 'left'; ctx.textBaseline = 'middle';
    ctx.font = size + 'px ' + family;
    let total = Array.from(text).reduce((s, a) => s + ctx.measureText(a).width, 0) + (text.length - 1) * tracking;
    if (total > maxWidth) { const fit = maxWidth / total; size *= fit; tracking *= fit; ctx.font = size + 'px ' + family; }
    total = Array.from(text).reduce((s, a) => s + ctx.measureText(a).width, 0) + (text.length - 1) * tracking;
    let left = x - total / 2; ctx.fillStyle = color;
    for (const a of text) { ctx.fillText(a, left, y); left += ctx.measureText(a).width + tracking; }
    ctx.restore();
  }
  function star(x, y, outer, inner, fill, rotation = -PI / 2) {
    const pts = [];
    for (let i = 0; i < 10; i++) { const a = rotation + i * PI / 5, r = i % 2 ? inner : outer; pts.push([x + r * Math.cos(a), y + r * Math.sin(a)]); }
    poly(pts, fill);
  }
  function treePath(r = 1) {
    const pts = [[0,-52],[-19,-27],[-10,-27],[-29,-3],[-17,-3],[-39,26],[-7,26],[-7,40],[7,40],[7,26],[39,26],[17,-3],[29,-3],[10,-27],[19,-27]];
    ctx.beginPath(); ctx.moveTo(pts[0][0] * r, pts[0][1] * r);
    for (let i = 1; i < pts.length; i++) ctx.lineTo(pts[i][0] * r, pts[i][1] * r);
    ctx.closePath();
  }
  function treeCookie(x, y, size, frosting = true) {
    ctx.save(); ctx.translate(x, y); treePath(size);
    ctx.fillStyle = C.biscuit; ctx.fill(); ctx.strokeStyle = C.edge; ctx.lineWidth = 2; ctx.stroke();
    if (frosting) {
      ctx.save(); ctx.scale(.78, .78); treePath(size); ctx.strokeStyle = C.cream; ctx.lineWidth = 3 / .78; ctx.lineJoin = 'round'; ctx.stroke(); ctx.restore();
      for (let i = 0; i < 5; i++) oval((i % 2 ? 10 : -9) * size, (-24 + i * 10) * size, 2.5 * size, 2.5 * size, i % 2 ? C.red : C.green);
    }
    ctx.restore();
  }
  function snowflake(x, y, r, color, rotation = 0) {
    ctx.save(); ctx.translate(x, y); ctx.rotate(rotation);
    for (let i = 0; i < 6; i++) {
      ctx.save(); ctx.rotate(i * PI / 3);
      line([[0,0],[0,-r]], color, 2.3);
      line([[-r*.22,-r*.61],[0,-r*.4],[r*.22,-r*.61]], color, 2.3);
      ctx.restore();
    }
    ctx.restore();
  }

  // Fixed perspective; no time-dependent scaling of cookies or machinery.
  const station = { x: 438, y: 690, radius: 126, depth: .51 };
  const cycle = mod(loopT, 5) / 5;
  const index = Math.floor(mod(loopT, duration) / 5);
  const indexEase = between(.73, .99, cycle);
  const tableAngle = -(index + indexEase) * PI / 2;
  const icingProgress = between(.15, .61, cycle);
  function spiral(u) {
    const a = -PI / 2 + u * TAU * 2.05, r = 2.7 + 21 * u;
    return [Math.cos(a) * r, Math.sin(a) * r];
  }
  const cookieY = station.y + station.radius * station.depth;
  function nozzlePose() {
    const p = spiral(icingProgress);
    const touching = [station.x + p[0], cookieY + p[1] * station.depth];
    const park = [station.x + 46, cookieY - 91];
    if (cycle < .15) { const u = between(.025, .15, cycle), first = spiral(0); return [lerp(park[0], station.x + first[0], u), lerp(park[1], cookieY + first[1] * station.depth, u)]; }
    if (cycle <= .61) return touching;
    const u = between(.61, .715, cycle);
    return [lerp(touching[0], park[0], u), lerp(touching[1], park[1], u)];
  }
  const nozzle = nozzlePose();

  function biscuit(x, y, r, icing, rotation = 0, pattern = 'spiral') {
    ctx.save(); ctx.translate(x, y); ctx.scale(1, station.depth); ctx.rotate(rotation);
    oval(0, 4, r, r, C.edge);
    const biscuitFill = ctx.createLinearGradient(-r, -r, r, r);
    biscuitFill.addColorStop(0, C.biscuitLight); biscuitFill.addColorStop(1, C.biscuit);
    oval(0, 0, r, r, biscuitFill, '#94603b', 1.1);
    oval(0, 0, r - 3.5, r - 3.5, null, '#dba973', .8);
    for (let n = 0; n < 9; n++) {
      const a = n * TAU / 9 + .3, rr = r * .84;
      oval(Math.cos(a) * rr, Math.sin(a) * rr, .9, .9, '#936139');
    }
    if (icing > 0) {
      ctx.lineCap = 'round'; ctx.lineJoin = 'round';
      if (pattern === 'spiral') {
        ctx.beginPath(); const first = spiral(0); ctx.moveTo(first[0], first[1]);
        const steps = Math.max(1, Math.ceil(icing * 132));
        for (let n = 1; n <= steps; n++) { const p = spiral(icing * n / steps); ctx.lineTo(p[0], p[1]); }
        ctx.strokeStyle = C.cream; ctx.lineWidth = 3.6; ctx.stroke();
      } else snowflake(0, 0, r * .65, C.cream, 0);
    }
    ctx.restore();
  }
  function pineSprig(x, y, angle, length) {
    ctx.save(); ctx.translate(x, y); ctx.rotate(angle);
    line([[0,0],[length,0]], '#5f6550', 2);
    for (let n = 0; n < 9; n++) {
      const q = 5 + n * (length - 12) / 9, len = 13 * (1 - n / 13);
      line([[q,0],[q + 7,-len]], n % 2 ? '#6b7d60' : C.green, 3);
      line([[q,0],[q + 7,len]], n % 2 ? C.green : '#6b7d60', 3);
    }
    ctx.restore();
  }
  function garland() {
    ctx.beginPath(); ctx.moveTo(205, 232); ctx.quadraticCurveTo(960, 376, 1715, 232);
    ctx.strokeStyle = '#8c8062'; ctx.lineWidth = 2; ctx.stroke();
    for (let i = 0; i <= 18; i++) {
      const u = i / 18, x = 205 + 1510 * u, y = 232 + 72 * 4 * u * (1 - u);
      const tangent = Math.atan2(288 * (1 - 2 * u), 1510);
      pineSprig(x, y, tangent + .42, 49);
      pineSprig(x, y, tangent - .42 + PI, 44);
      if (i % 3 === 0) {
        line([[x,y],[x,y+18]], '#8c8062', 1.5);
        round(x - 3, y + 16, 6, 6, 1, C.brass);
        oval(x, y + 27, 4.7, 6.5, '#e7d7a6', '#aa946a', 1);
      }
      if (i % 3 === 1) for (let n = 0; n < 3; n++) oval(x + n * 6 - 6, y + 5 + (n % 2) * 5, 3.8, 3.8, C.red);
    }
  }
  function workshopRig() {
    round(227, 474, 21, 324, 5, C.greenDark);
    round(215, 788, 48, 17, 4, '#20372f');
    round(227, 473, 294, 24, 5, C.green);
    round(244, 482, 258, 3, 1, '#8c9c7e');
    for (const x of [240, 507]) oval(x, 486, 3, 3, C.brass);
    round(nozzle[0] - 15, 469, 30, 31, 3, '#b79864', '#8b7048', 1);
    round(nozzle[0] - 4, 499, 8, nozzle[1] - 596, 2, '#aab0a4');
  }
  function turntable() {
    oval(station.x, station.y + 20, 186, 186 * station.depth, '#274239');
    ctx.fillStyle = C.green; ctx.fillRect(station.x - 186, station.y, 372, 22);
    oval(station.x, station.y, 186, 186 * station.depth, '#d4c3a2', '#9c8663', 2);
    oval(station.x, station.y, 174, 174 * station.depth, '#eee0c3', '#b49b70', 1.5);
    oval(station.x, station.y, 78, 78 * station.depth, '#d9c8a4', '#b49b70', 1.5);
    for (let i = 0; i < 12; i++) {
      const a = tableAngle + i * TAU / 12;
      const p = [station.x + 165 * Math.cos(a), station.y + 165 * station.depth * Math.sin(a)];
      const q = [station.x + 171 * Math.cos(a), station.y + 171 * station.depth * Math.sin(a)];
      line([p,q], '#9c8663', 1.2);
    }
    const slots = [];
    for (let i = 0; i < 4; i++) {
      const a = PI / 2 + tableAngle + i * PI / 2;
      const x = station.x + station.radius * Math.cos(a), y = station.y + station.radius * station.depth * Math.sin(a);
      const aWrapped = mod(a, TAU);
      const processed = aWrapped < PI / 2 - 1e-7 || aWrapped > PI * 1.5;
      const icing = i === index % 4 ? icingProgress : processed ? 1 : 0;
      slots.push({x,y,icing,rotation:a-PI/2});
    }
    slots.sort((a,b) => a.y - b.y);
    for (const slot of slots) {
      oval(slot.x, slot.y + 1.5, 39, 39 * station.depth, '#d1bd94', '#a99165', 1);
      biscuit(slot.x, slot.y, 31, slot.icing, slot.rotation);
    }
    round(258, 584, 360, 65, 11, C.redDark);
    round(268, 589, 340, 48, 8, C.red);
    line([[278,642],[598,642]], '#b77b66', 2);
    tracked('GINGER & SPICE', 336, 613, 10, 1.2, 130, '#f0debb');
    oval(station.x, station.y, 10, 4.8, C.brass);
    oval(station.x, station.y, 4, 2, '#766547');
    round(329, 785, 218, 28, 5, C.greenDark);
    tracked('ICING STATION', 438, 800, 10, 2, 194, '#e5d9bb');
  }
  function pipingBag() {
    ctx.save(); ctx.translate(nozzle[0], nozzle[1]);
    round(-10, -103, 20, 12, 3, '#9b8059');
    ctx.beginPath(); ctx.moveTo(-10, -96); ctx.bezierCurveTo(-40,-70,-24,-42,-6,-18);
    ctx.lineTo(6,-18); ctx.bezierCurveTo(24,-42,40,-70,10,-96); ctx.closePath();
    const fill = ctx.createLinearGradient(-25,-75,25,-45);
    fill.addColorStop(0,'#ecddbe'); fill.addColorStop(.48,'#fff7e5'); fill.addColorStop(1,'#d7c4a0');
    ctx.fillStyle = fill; ctx.fill(); ctx.strokeStyle = '#ae9874'; ctx.lineWidth = 1.3; ctx.stroke();
    ctx.beginPath(); ctx.moveTo(-23,-74); ctx.quadraticCurveTo(0,-64,23,-74); ctx.lineTo(19,-60); ctx.quadraticCurveTo(0,-52,-19,-60); ctx.closePath(); ctx.fillStyle = C.red; ctx.fill();
    line([[-5,-89],[-12,-76]], '#ccb891', 1.1);
    poly([[-6,-19],[6,-19],[2,0],[-2,0]], '#a4aaa1', '#777e75', 1);
    line([[-2,-16],[2,-16]], '#e0e4da', 1.2);
    ctx.restore();
  }

  function gingerMan(x, y, s = 1, rot = 0, accent = C.red) {
    ctx.save(); ctx.translate(x, y); ctx.rotate(rot); ctx.scale(s, s);
    const body = (dy, col, wAdd = 0) => {
      ctx.save(); ctx.translate(0, dy);
      ctx.lineCap = 'round'; ctx.lineJoin = 'round';
      line([[-34, -14], [34, -14]], col, 20 + wAdd);
      line([[0, -18], [-20, 42]], col, 22 + wAdd);
      line([[0, -18], [20, 42]], col, 22 + wAdd);
      round(-20 - wAdd / 2, -30 - wAdd / 2, 40 + wAdd, 46 + wAdd, 16, col);
      oval(0, -52, 23 + wAdd / 2, 23 + wAdd / 2, col);
      ctx.restore();
    };
    body(4, C.edge, 4);
    body(0, C.biscuit, 0);
    oval(-7, -55, 2.6, 2.6, C.cream);
    oval(7, -55, 2.6, 2.6, C.cream);
    oval(-12, -49, 3.2, 2.2, accent);
    oval(12, -49, 3.2, 2.2, accent);
    ctx.beginPath(); ctx.arc(0, -49, 7.5, 0.2 * PI, 0.8 * PI);
    ctx.strokeStyle = C.cream; ctx.lineWidth = 2.6; ctx.stroke();
    poly([[-10, -32], [0, -28], [-10, -24]], accent);
    poly([[10, -32], [0, -28], [10, -24]], accent);
    oval(0, -28, 3.5, 3.5, C.cream);
    for (let i = 0; i < 3; i++) {
      oval(0, -14 + i * 11, 4.2, 4.2, C.cream);
      oval(0, -14 + i * 11, 2.8, 2.8, i % 2 ? C.green : accent);
    }
    line([[-31, -21], [-27, -14], [-31, -7]], C.cream, 3);
    line([[31, -21], [27, -14], [31, -7]], C.cream, 3);
    line([[-26, 33], [-19, 37], [-12, 35]], C.cream, 3);
    line([[12, 35], [19, 37], [26, 33]], C.cream, 3);
    ctx.restore();
  }

  function starCookie(x, y, r, rot = -PI / 2) {
    ctx.save(); ctx.translate(x, y);
    star(0, 4, r + 2, (r + 2) * 0.48, C.edge, rot);
    star(0, 0, r, r * 0.48, C.biscuit, rot);
    star(0, 0, r * 0.78, r * 0.38, C.cream, rot);
    star(0, 0, r * 0.68, r * 0.33, C.biscuitLight, rot);
    oval(0, 0, r * 0.16, r * 0.16, C.red, C.cream, 2);
    for (let i = 0; i < 5; i++) {
      const a = rot + i * TAU / 5;
      oval(Math.cos(a) * r * 0.52, Math.sin(a) * r * 0.52, 2.2, 2.2, i % 2 ? C.green : C.red);
    }
    ctx.restore();
  }

  function heartCookie(x, y, s = 1, rot = 0) {
    ctx.save(); ctx.translate(x, y); ctx.rotate(rot); ctx.scale(s, s);
    const heartPath = (dy, sc) => {
      ctx.save(); ctx.translate(0, dy); ctx.scale(sc, sc);
      ctx.beginPath();
      ctx.moveTo(0, 28);
      ctx.bezierCurveTo(-42, 2, -44, -28, -21, -36);
      ctx.bezierCurveTo(-7, -41, 0, -27, 0, -18);
      ctx.bezierCurveTo(0, -27, 7, -41, 21, -36);
      ctx.bezierCurveTo(44, -28, 42, 2, 0, 28);
      ctx.closePath();
      ctx.restore();
    };
    heartPath(4, 1.05); ctx.fillStyle = C.edge; ctx.fill();
    heartPath(0, 1); ctx.fillStyle = C.biscuit; ctx.fill();
    ctx.strokeStyle = C.edge; ctx.lineWidth = 2; ctx.stroke();
    heartPath(0, 0.78); ctx.strokeStyle = C.cream; ctx.lineWidth = 3.5; ctx.stroke();
    snowflake(0, -6, 13, C.cream, 0);
    oval(0, -6, 3.5, 3.5, C.red);
    ctx.restore();
  }

  function bellCookie(x, y, s = 1, rot = 0) {
    ctx.save(); ctx.translate(x, y); ctx.rotate(rot); ctx.scale(s, s);
    const bellShape = (dy) => {
      ctx.beginPath();
      ctx.moveTo(-28, 20 + dy);
      ctx.quadraticCurveTo(-22, -28 + dy, 0, -34 + dy);
      ctx.quadraticCurveTo(22, -28 + dy, 28, 20 + dy);
      ctx.closePath();
    };
    oval(0, 24, 9, 9, C.edge);
    bellShape(4); ctx.fillStyle = C.edge; ctx.fill();
    oval(0, 21, 8, 8, C.biscuit, C.edge, 1.8);
    bellShape(0); ctx.fillStyle = C.biscuit; ctx.fill();
    ctx.strokeStyle = C.edge; ctx.lineWidth = 2; ctx.stroke();
    line([[-22, 13], [-11, 8], [0, 13], [11, 8], [22, 13]], C.cream, 3.5);
    oval(0, -28, 6, 4, C.red);
    oval(-6, -12, 3, 3, C.green); oval(6, -12, 3, 3, C.green);
    ctx.restore();
  }

  function house() {
    ctx.save(); ctx.translate(981, 718);
    const cookieScale = 0.65;

    oval(40, 38, 269, 48, '#a78c65');
    ctx.fillStyle = '#a78c65'; ctx.fillRect(-229, 27, 538, 11);
    oval(40, 26, 269, 47, '#e3d4b7', '#b8a07c', 1.5);
    oval(40, 25, 253, 40, '#fff3dc');

    // Penyangga nampan bertingkat untuk aneka kue jahe
    round(28, -235, 24, 260, 6, C.brass, '#8b7048', 1.5);
    oval(40, 22, 42, 10, C.brass, '#8b7048', 1.2);

    // Tingkat bawah: Aneka kue jahe dengan scale yang lebih kecil
    treeCookie(-165, -4, 1.15 * cookieScale, true);
    heartCookie(-92, 6, 1.05 * cookieScale, -0.14);
    gingerMan(-8, -10, 1.12 * cookieScale, -0.05, C.red);
    gingerMan(88, -10, 1.10 * cookieScale, 0.08, C.green);
    heartCookie(168, 5, 1.02 * cookieScale, 0.16);
    treeCookie(230, -3, 1.08 * cookieScale, true);
    for (let i = 0; i < 7; i++) oval(-125 + i * 54, 22, 4.2, 3, i % 2 ? C.red : C.green);

    // Nampan tingkat tengah
    oval(40, -106, 178, 28, '#a78c65');
    oval(40, -112, 178, 27, '#e3d4b7', '#b8a07c', 1.4);
    oval(40, -113, 164, 22, '#fff3dc');
    oval(40, -110, 26, 7, C.brass, '#8b7048', 1);

    // Tingkat tengah: Kue Lonceng, Bintang, dan Gingerbread Man
    bellCookie(-70, -129, 1.02 * cookieScale, -0.12);
    starCookie(2, -135, 42 * cookieScale, -PI / 2 - 0.08);
    gingerMan(74, -138, 0.96 * cookieScale, 0.06, C.red);
    bellCookie(142, -128, 1.0 * cookieScale, 0.14);

    // Nampan tingkat atas & kue bintang puncak
    oval(40, -226, 106, 18, '#a78c65');
    oval(40, -231, 106, 17, '#e3d4b7', '#b8a07c', 1.3);
    oval(40, -232, 95, 13, '#fff3dc');
    treeCookie(-10, -252, 0.78 * cookieScale, true);
    treeCookie(90, -252, 0.78 * cookieScale, true);
    starCookie(40, -262, 48 * cookieScale, -PI / 2);

    ctx.restore();
  }

  function miniHouse(x, y, size) {
    gingerMan(x, y - 24 * size, size * 0.45, 0, C.red);
  }

  function rack() {
    const x=1518;
    round(x-166,476,16,327,3,C.greenDark);round(x+150,476,16,327,3,C.greenDark);
    round(x-177,469,354,18,4,C.green);
    for(const y of [585,688,791]){
      round(x-174,y,348,14,4,'#9d7750');round(x-174,y,348,4,2,'#cfb18a');
      line([[x-157,y+14],[x-157,y+21],[x+157,y+21],[x+157,y+14]],'#bd9c72',1.3);
    }
    for(const dx of [-96,0,96])miniHouse(x+dx,585,.83);
    for(const dx of [-99,0,99])treeCookie(x+dx,688-40*.73,.73);
    for(let i=0;i<4;i++){
      ctx.save();ctx.translate(x-116+i*77,791-25*.86);ctx.scale(1,.86);
      oval(0,0,25,25,C.biscuit,C.edge,1.5);snowflake(0,0,17,C.cream,i*PI/6);ctx.restore();
    }
    round(x-96,427,192,29,5,C.paper,C.brass,1.2);
    tracked('FRESHLY BAKED',x,442,11,2.1,168,C.ink);
    for(const dx of [-61,61])line([[x+dx,456],[x+dx,469]],C.brass,1.2);
    round(x-177,800,354,19,4,C.greenDark);
  }
  function belt() {
    const x=551,y=865,w=1014;
    round(585,665,58,184,16,C.redDark);
    round(595,674,38,161,11,C.red);
    line([[605,681],[605,824]],'#a06b59',1.4);
    round(x,y-37,w,82,27,C.greenDark);
    round(x+8,y-32,w-16,61,25,'#c6b28e');
