  function snow(front) {
    let cache = draw._midnightSnowV2;
    if (!cache) {
      function makeLayer(count, frontLayer) {
        const data = [];
        for (let i = 0; i < count; i++) {
          const id = i + (frontLayer ? 401 : 19);
          data.push({
            offset: fract((i + 0.5 + hash(id) * 0.18) / count),
            lane: (fract((i + 0.5) * 0.61803398875 + (frontLayer ? 0.27 : 0)) * 2 - 1) * 294,
            sway: 5 + hash(id + 7) * 4,
            angle: hash(id + 21) * TAU,
            size: (frontLayer ? 1.35 : 0.9) + hash(id + 81) * (frontLayer ? 1.0 : 0.8),
            crystal: i % 11 === 0
          });
        }
        return data;
      }
      cache = { back: makeLayer(76, false), near: makeLayer(30, true) };
      draw._midnightSnowV2 = cache;
    }
    const data = front ? cache.near : cache.back;
    const wind = 2.8 * Math.sin(phase + 0.35);
    for (let i = 0; i < data.length; i++) {
      const p = data[i];
      const q = fract(sceneProgress + p.offset);
      // Positive vertical velocity throughout: no reversals or speed jumps.
      const flow = q + 0.010 * (Math.sin(TAU * q + p.angle) - Math.sin(p.angle));
      const y = 150 + flow * 600;
      const x = globe.x + p.lane + p.sway * Math.sin(TAU * q + p.angle) + wind;
      const distance = Math.hypot(x - globe.x, y - globe.y);
      const clearance = globe.radius - 11 - distance - p.size * 1.4;
      const boundary = smooth(clearance / 16);
      const recycle = smooth(q / 0.075) * smooth((1 - q) / 0.11);
      const opacity = (front ? 0.60 : 0.43) * boundary * recycle;
      if (opacity <= 0) continue;
      ctx.save(); ctx.globalAlpha = opacity;
      if (p.crystal) {
        ctx.translate(x, y);
        ctx.rotate(p.angle + phase);
        diamond(0, 0, p.size * 1.20, '#eff4f1');
      } else ellipse(x, y, p.size, p.size, '#eff4f1');
      ctx.restore();
    }
  }

