  function pineBranch(x, y, mirror) {
    ctx.save(); ctx.translate(x, y); ctx.scale(mirror, 1);
    function stemPoint(u) {
      const v = 1 - u;
      return {
        x: 3 * v * v * u * 61 + 3 * v * u * u * 119 + u * u * u * 176,
        y: -3 * v * v * u * 19 - 3 * v * u * u * 62 - u * u * u * 77,
        dx: 3 * v * v * 61 + 6 * v * u * 58 + 3 * u * u * 57,
        dy: -3 * v * v * 19 - 6 * v * u * 43 - 3 * u * u * 15
