    ctx.strokeStyle = '#8d8a6a'; ctx.lineWidth = 2.2; ctx.lineCap = 'round';
    ctx.beginPath(); ctx.moveTo(0, 0); ctx.bezierCurveTo(61, -19, 119, -62, 176, -77); ctx.stroke();
    for (let b = 0; b < 7; b++) {
      const u = (b + 1) / 8;
      const root = stemPoint(u);
      const length = Math.hypot(root.dx, root.dy);
      const tx = root.dx / length, ty = root.dy / length;
      const nx = -ty, ny = tx;
      for (const side of [-1, 1]) {
        const endX = root.x + tx * 15 + nx * side * (25 - u * 9);
        const endY = root.y + ty * 15 + ny * side * (25 - u * 9);
        const twigLength = Math.hypot(endX - root.x, endY - root.y);
        const ux = (endX - root.x) / twigLength, uy = (endY - root.y) / twigLength;
        const vx = -uy, vy = ux;
        ctx.beginPath(); ctx.moveTo(root.x, root.y); ctx.lineTo(endX, endY);
        ctx.strokeStyle = '#697e73'; ctx.lineWidth = 1.1; ctx.stroke();
        for (let k = 1; k <= 6; k++) {
          const q = k / 7;
          const px = root.x + (endX - root.x) * q;
          const py = root.y + (endY - root.y) * q;
          for (const spread of [-1, 1]) {
            const tipX = px + ux * (7 - q * 1.5) + vx * spread * (6.5 - q * 2);
            const tipY = py + uy * (7 - q * 1.5) + vy * spread * (6.5 - q * 2);
            ctx.beginPath();
            ctx.moveTo(px - vx * 0.60, py - vy * 0.60);
            ctx.quadraticCurveTo((px + tipX) * 0.5 + vx * spread * 0.8,
              (py + tipY) * 0.5 + vy * spread * 0.8, tipX, tipY);
            ctx.lineTo(px + vx * 0.60, py + vy * 0.60);
            ctx.closePath();
            ctx.fillStyle = (b + k + (spread > 0 ? 1 : 0)) % 3 === 0 ? '#819c92' : '#41675f';
            ctx.fill();
