function draw(ctx, time, width, height) {
  if (!ctx || !Number.isFinite(time) || !(width > 0) || !(height > 0)) return;

  const t = time;
  const duration = 20;
  const sceneCount = 1;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  const TAU = Math.PI * 2;
  const phase = TAU * (currentScene + sceneProgress);
  const scale = Math.min(width / 1920, minSide / 1080);
  const PI = Math.PI;

  const palette = {
    night: '#071c19',
    dark: '#0a2722',
    panel: '#0d3029',
    green: '#124438',
    lightGreen: '#1d5848',
    gold: '#c6a363',
    goldLight: '#eddbb0',
    goldDark: '#81623b',
