    ctx.translate(x, y);
    ctx.fillStyle = lineGradient(-size, -size * 0.7, size, size * 0.3,
      cream ? [[0, '#d5bd88'], [0.5, '#f1e1bb'], [1, '#ad8b51']]
        : [[0, '#9b7040'], [0.5, '#e5c98f'], [1, '#a37842']]);
    for (const side of [-1, 1]) {
      ctx.beginPath();
      ctx.moveTo(side * 2, 1);
      ctx.bezierCurveTo(side * size * 0.54, -size * 0.84,
        side * size * 1.12, -size * 0.77, side * size, -size * 0.18);
      ctx.bezierCurveTo(side * size * 0.93, size * 0.13,
        side * size * 0.35, size * 0.15, side * 2, 1);
      ctx.closePath(); ctx.fill();
      ctx.strokeStyle = '#d6bc83'; ctx.lineWidth = 0.9; ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(side * 4, 1);
      ctx.lineTo(side * size * 0.62, size * 0.37);
      ctx.lineTo(side * size * 0.55, size * 0.76);
      ctx.lineTo(side * size * 0.3, size * 0.56);
      ctx.lineTo(side * size * 0.13, size * 0.66);
      ctx.closePath(); ctx.fill();
    }
    roundedRect(-5.5, -6, 11, 13, 3);
    ctx.fillStyle = '#d5b575'; ctx.fill();
    ctx.strokeStyle = '#efdcac'; ctx.lineWidth = 0.8; ctx.stroke();
    ctx.restore();
  }

  function drawGift(x, y, w, h, cream, offset) {
    const dx = 27, dy = -18;
    const frontColors = cream
      ? [[0, '#cbb993'], [0.48, '#eddfc2'], [1, '#cbb58b']]
      : [[0, '#5c2230'], [0.5, '#8d3b4c'], [1, '#632333']];
    const ribbon = cream ? '#78313e' : '#c9a56a';
    const ribbonLight = cream ? '#ad5f68' : '#efdab0';

    // Contact is contained within the supporting plinth's top ellipse.
    ellipse(x + w * 0.5 + dx * 0.45, y + h - 0.5, w * 0.54, 8,
      'rgba(0,15,9,0.20)');

    ctx.beginPath();
    ctx.moveTo(x + w, y); ctx.lineTo(x + w + dx, y + dy);
    ctx.lineTo(x + w + dx, y + h + dy); ctx.lineTo(x + w, y + h);
    ctx.closePath();
    ctx.fillStyle = cream ? '#a89570' : '#4d1e2c'; ctx.fill();

    ctx.fillStyle = lineGradient(x, y, x + w, y, frontColors);
    ctx.fillRect(x, y, w, h);
    ctx.strokeStyle = cream ? '#c0aa80' : '#9b5260';
    ctx.lineWidth = 0.8; ctx.strokeRect(x + 0.4, y + 0.4, w - 0.8, h - 0.8);

    ctx.save();
    ctx.beginPath(); ctx.rect(x + 1, y + 1, w - 2, h - 2); ctx.clip();
    ctx.globalAlpha = cream ? 0.20 : 0.27;
    ctx.fillStyle = cream ? '#9a8050' : '#e0b576';
    for (let row = 0; row < 3; row++) {
      for (let col = 0; col < 4; col++) {
        const px = x + 15 + col * (w - 30) / 3;
        const py = y + 18 + row * (h - 36) / 2;
        if (Math.abs(px - (x + w * 0.5)) > w * 0.15) {
          starPath(px, py, 3.1, 1.2, 4, 0); ctx.fill();
        }
      }
    }
    ctx.restore();

    ctx.fillStyle = ribbon;
    ctx.fillRect(x + w * 0.5 - 10, y, 20, h);
    ctx.fillStyle = ribbonLight;
    ctx.fillRect(x + w * 0.5 - 9, y, 1.5, h);

    const lx = x - 5, ly = y - 12, lw = w + 10, lh = 17;
    ctx.beginPath();
    ctx.moveTo(lx, ly); ctx.lineTo(lx + dx, ly + dy);
    ctx.lineTo(lx + lw + dx, ly + dy); ctx.lineTo(lx + lw, ly);
    ctx.closePath();
    ctx.fillStyle = cream ? '#f0e4ca' : '#a04e5c'; ctx.fill();

    ctx.beginPath();
    ctx.moveTo(lx + lw, ly); ctx.lineTo(lx + lw + dx, ly + dy);
    ctx.lineTo(lx + lw + dx, ly + lh + dy); ctx.lineTo(lx + lw, ly + lh);
    ctx.closePath();
    ctx.fillStyle = cream ? '#bbaa83' : '#612333'; ctx.fill();
    ctx.fillStyle = cream ? '#dfcfad' : '#813445';
    ctx.fillRect(lx, ly, lw, lh);
    ctx.fillStyle = ribbon;
    ctx.fillRect(x + w * 0.5 - 10, ly, 20, lh);

    ctx.beginPath();
    ctx.moveTo(x + w * 0.5 - 10, ly);
    ctx.lineTo(x + w * 0.5 - 10 + dx, ly + dy);
    ctx.lineTo(x + w * 0.5 + 10 + dx, ly + dy);
    ctx.lineTo(x + w * 0.5 + 10, ly);
    ctx.closePath(); ctx.fill();

    // A restrained, clipped change in surface reflection, with no halo.
    ctx.save();
    ctx.beginPath(); ctx.rect(x, y + 6, w, h - 6); ctx.clip();
    const sx = x + w * (0.5 + 0.30 * Math.sin(phase + offset));
    ctx.fillStyle = lineGradient(sx - 12, 0, sx + 12, 0, [
      [0, 'rgba(255,241,208,0)'], [0.5, 'rgba(255,241,208,0.045)'],
      [1, 'rgba(255,241,208,0)']
    ]);
    ctx.fillRect(x, y, w, h);
    ctx.restore();
    drawBow(x + w * 0.5 + dx * 0.45, ly + dy * 0.45 - 3, 31, !cream);
  }

  function shadedBauble(x, y, r, burgundy, amount) {
    ctx.save();
    ctx.translate(x, y);
    const grad = ctx.createRadialGradient(-r * 0.32, -r * 0.37, r * 0.06, 0, 0, r * 1.04);
    if (burgundy) {
      grad.addColorStop(0, '#b46b72'); grad.addColorStop(0.35, '#8a3b4a');
      grad.addColorStop(0.78, '#602533'); grad.addColorStop(1, '#421d29');
    } else {
      grad.addColorStop(0, '#ecdbb3'); grad.addColorStop(0.35, '#ccaf74');
      grad.addColorStop(0.78, '#a07c42'); grad.addColorStop(1, '#6b512b');
    }
    ellipse(0, 0, r, r, grad, burgundy ? '#b9787a' : '#d9c18b', 1);

    ctx.save();
    ctx.beginPath(); ctx.arc(0, 0, r - 0.8, 0, TAU); ctx.clip();
    ctx.strokeStyle = burgundy ? '#b87777' : '#ead8af';
    ctx.globalAlpha = 0.4;
    ctx.lineWidth = 1;
    for (let i = -1; i <= 1; i++) {
      ctx.beginPath();
      ctx.ellipse(i * r * 0.32, 0, r * (0.24 + 0.02 * amount), r * 1.02,
        -0.14 + amount * 0.015, 0, TAU);
      ctx.stroke();
    }
    ctx.globalAlpha = 0.25;
    ctx.fillStyle = '#fff0cf';
    ctx.beginPath();
    ctx.ellipse(-r * 0.33, -r * 0.36, r * 0.11, r * 0.24, 0.6, 0, TAU);
    ctx.fill();
    ctx.restore();

    roundedRect(-r * 0.18, -r - 4, r * 0.36, r * 0.17, 1.5);
    ctx.fillStyle = lineGradient(-r * 0.18, 0, r * 0.18, 0,
      [[0, '#8f7443'], [0.45, '#e7cfa0'], [1, '#a2854e']]);
    ctx.fill();
    ctx.restore();
  }

  function hangingBauble(anchorX, anchorY, length, r, burgundy, offset) {
    // The collar is fixed to the brass rail. Only the string and ornament
    // rotate about that physical attachment point.
    ellipse(anchorX, anchorY, 4.1, 4.1, '#b59a63', '#e0ca99', 0.9);
    const angle = 0.018 * Math.sin(phase * 2 + offset);
    ctx.save();
    ctx.translate(anchorX, anchorY);
    ctx.rotate(angle);
    ctx.strokeStyle = '#ac9769'; ctx.lineWidth = 1.1;
    ctx.beginPath();
    ctx.moveTo(0, 3);
    ctx.lineTo(0, length - r - 7);
    ctx.stroke();
    ellipse(0, length - r - 5.5, 2.4, 3.1, null, '#c9b180', 1);
    shadedBauble(0, length, r, burgundy, Math.sin(phase + offset));
    ctx.restore();
  }

  function drawHangingInstallation() {
    // These dimensions exactly match the INNER outlines of the wall panels.
    // The reinforced upper rail shares the same quadratic corner geometry.
    const panelWidth = 346;
    const cornerRadius = 166;
    const top = 194;
    const spring = top + cornerRadius;
    const spacing = panelWidth * 0.2023121387;

    function railY(x, left) {
      const right = left + panelWidth;
      const innerDistance = Math.min(x - left, right - x);
      if (innerDistance >= cornerRadius) return top;
      const q = 1 - Math.sqrt(Math.max(0, innerDistance) / cornerRadius);
      return top + cornerRadius * q * q;
    }

    for (let panel = 0; panel < 2; panel++) {
      const center = panel === 0 ? 303 : 1617;
      const left = center - panelWidth * 0.5;
      const right = center + panelWidth * 0.5;
      ctx.beginPath();
      ctx.moveTo(left, spring);
      ctx.quadraticCurveTo(left, top, left + cornerRadius, top);
      ctx.lineTo(right - cornerRadius, top);
      ctx.quadraticCurveTo(right, top, right, spring);
      ctx.strokeStyle = '#a08c59';
      ctx.lineWidth = 2.0;
      ctx.stroke();

      // Equal horizontal offsets and identical mounting heights establish
      // a deliberate, mirrored arrangement on the architectural support.
      for (let slot = 0; slot < 2; slot++) {
        const x = center + (slot === 0 ? -spacing : spacing);
        const y = railY(x, left);
        const large = panel === 0 ? slot === 0 : slot === 1;
        const r = large ? 36 : 25;
        const ballY = large ? 435 : 339;
        const offset = large ? (panel === 0 ? 0.6 : 1.4) : (panel === 0 ? 2.4 : 3.0);
        hangingBauble(x, y, ballY - y, r, large, offset);
      }
    }
  }

  function pineSpray(rootX, rootY, mirror) {
    ctx.save();
    ctx.translate(rootX, rootY);
    ctx.scale(mirror, 1);
    ctx.strokeStyle = '#8e784c'; ctx.lineWidth = 2.4; ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(0, 0); ctx.bezierCurveTo(4, -41, -8, -96, 0, -151); ctx.stroke();
    for (let level = 0; level < 5; level++) {
      const y = -21 - level * 24;
      const reach = 52 - level * 7;
      for (const side of [-1, 1]) {
        const tipX = side * reach;
        const tipY = y - 38;
        ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(tipX, tipY);
        ctx.lineWidth = 1.25; ctx.strokeStyle = '#5f7250'; ctx.stroke();
        for (let needle = 1; needle <= 6; needle++) {
          const u = needle / 7;
          const nx = tipX * u;
          const ny = y + (tipY - y) * u;
          const needleLength = 11 - u * 3;
          for (const spread of [-1, 1]) {
            const tx = nx + side * (9 + spread * 4);
            const ty = ny - needleLength + spread * 7;
            ctx.beginPath(); ctx.moveTo(nx - side * 1.4, ny + 1);
            ctx.quadraticCurveTo((nx + tx) * 0.5 - spread * 2, (ny + ty) * 0.5 - 1, tx, ty);
            ctx.quadraticCurveTo((nx + tx) * 0.5 + spread * 2, (ny + ty) * 0.5 + 2, nx + side * 1.5, ny + 1);
            ctx.closePath();
            ctx.fillStyle = (needle + level + (spread === 1 ? 1 : 0)) % 3 === 0
              ? '#618268' : '#315e47';
            ctx.fill();
          }
        }
      }
    }
    for (const b of [[-7, -42], [5, -34], [1, -49]]) {
      ellipse(b[0], b[1], 5.5, 5.5, '#8e3d48', '#b06b66', 0.8);
      ellipse(b[0] - 1.3, b[1] - 1.6, 1, 1, '#d1a08a');
    }
    ctx.restore();
  }

  function drawGoldFlecks() {
    // Dedicated empty corridors keep particles clear of the tree and gifts.
    for (let side = 0; side < 2; side++) {
      for (let i = 0; i < 9; i++) {
        const u = ((sceneProgress * (1 + i % 2) + i / 9 + side * 0.17) % 1 + 1) % 1;
        const envelope = Math.sin(PI * u);
        const x = (side === 0 ? 537 : 1383) + 11 * Math.sin(phase + i * 1.7);
        const y = 710 - u * 430;
        const r = 1.7 + (i % 3) * 0.45;
        ctx.save();
        ctx.globalAlpha = 0.34 * envelope * envelope;
        ctx.translate(x, y);
        ctx.rotate(phase + i * 0.6);
        ctx.fillStyle = '#dbc38b';
        ctx.beginPath();
        ctx.moveTo(0, -r * 1.4); ctx.lineTo(r * 0.6, 0);
        ctx.lineTo(0, r * 1.4); ctx.lineTo(-r * 0.6, 0);
        ctx.closePath(); ctx.fill();
        ctx.restore();
      }
    }
  }

  ctx.save();
  try {
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.globalAlpha = 1;
    ctx.globalCompositeOperation = 'source-over';
    ctx.shadowBlur = 0;
    ctx.shadowOffsetX = 0;
    ctx.shadowOffsetY = 0;
    ctx.shadowColor = 'rgba(0,0,0,0)';
    if ('filter' in ctx) ctx.filter = 'none';
    ctx.setLineDash([]);
    ctx.lineDashOffset = 0;
    ctx.lineCap = 'butt';
    ctx.lineJoin = 'round';
    ctx.miterLimit = 2;
    ctx.fillStyle = palette.night;
    ctx.fillRect(0, 0, width, height);
    ctx.translate(width * 0.5, height * 0.5);
    ctx.scale(scale, scale);
    ctx.translate(-960, -540);

    drawArchitecture();
    drawGoldFlecks();

    drawHangingInstallation();

    drawPlatforms();
    drawTree();
    drawGift(300, 759, 120, 116, false, 0.8);
    drawGift(1470, 771, 132, 104, true, 3.4);

    pineSpray(171, 964, 1);
    pineSpray(1749, 964, -1);
    ellipse(525, 1000, 26, 4.5, 'rgba(0,12,9,0.20)');
    ellipse(1395, 1000, 26, 4.5, 'rgba(0,12,9,0.20)');
    shadedBauble(525, 978, 22, false, Math.sin(phase));
    shadedBauble(1395, 978, 22, true, Math.sin(phase + PI));

    // Small flat metallic accents on the floor; kept outside all swept bounds.
    ellipse(306, 989, 13, 4, '#b59a65', '#dbc18b', 0.8);
    ellipse(1614, 989, 13, 4, '#b59a65', '#dbc18b', 0.8);
  } finally {
    ctx.restore();
    ctx.beginPath();
  }
}

